package com.aoo.bcg.gamespi;import static org.junit.jupiter.api.Assertions.*;import java.time.Duration;import org.junit.jupiter.api.Test;
class RuntimeWorkBudgetTest{@Test void failsClosedOnEveryRuntimeDimension(){var steps=new RuntimeWorkBudget(1,2,2,10,Duration.ofSeconds(1));steps.step();assertThrows(RuntimeWorkBudget.BudgetExceededException.class,steps::step);var depth=new RuntimeWorkBudget(1,2,2,10,Duration.ofSeconds(1));assertThrows(RuntimeWorkBudget.BudgetExceededException.class,()->depth.depth(3));var queue=new RuntimeWorkBudget(1,2,2,10,Duration.ofSeconds(1));queue.enqueue(2,10);assertThrows(RuntimeWorkBudget.BudgetExceededException.class,()->queue.enqueue(1,0));var memory=new RuntimeWorkBudget(1,2,2,10,Duration.ofSeconds(1));assertThrows(RuntimeWorkBudget.BudgetExceededException.class,()->memory.enqueue(1,11));var elapsed=new RuntimeWorkBudget(1,2,2,10,Duration.ofNanos(1));assertThrows(RuntimeWorkBudget.BudgetExceededException.class,elapsed::checkTime);}}
